} else if (key === "Escape") {
  // Hitting Escape:
  // - Closes submenu.
  // - Moves focus to parent menubar item.
  preventEvent(event);
  const parentMenu = this.elements.parentMenu;
  if (parentMenu) {
    const toggle = parentMenu.elements.submenuToggles.find(
      t => t.elements.controlledMenu === this
    );
    if (toggle) {
      toggle.close();
      toggle.dom.toggle.focus();
    }
  }
}
